import unittest

from solution import first_lucas_term_with_digits


def independent_expected(digits):
    threshold = 10 ** (digits - 1)
    previous, current = 2, 1
    if previous >= threshold:
        return 0
    if current >= threshold:
        return 1
    index = 1
    while current < threshold:
        previous, current = current, previous + current
        index += 1
    return index


class FirstLucasTermTests(unittest.TestCase):
    def test_documented_and_small_boundaries(self):
        self.assertEqual(first_lucas_term_with_digits(1), 0)
        self.assertEqual(first_lucas_term_with_digits(2), 5)
        self.assertEqual(first_lucas_term_with_digits(3), 10)
        self.assertEqual(first_lucas_term_with_digits(4), 15)

    def test_larger_inputs_use_exact_digit_thresholds(self):
        for digits in (5, 10, 25, 75, 200):
            with self.subTest(digits=digits):
                self.assertEqual(
                    first_lucas_term_with_digits(digits),
                    independent_expected(digits),
                )

    def test_non_integer_values_and_booleans_raise_type_error(self):
        for value in (True, False, 1.0, "2", None, [2]):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    first_lucas_term_with_digits(value)

    def test_nonpositive_integers_raise_value_error(self):
        for value in (0, -1, -100):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    first_lucas_term_with_digits(value)

    def test_repeated_calls_are_independent(self):
        large = first_lucas_term_with_digits(40)
        self.assertEqual(first_lucas_term_with_digits(1), 0)
        self.assertEqual(large, independent_expected(40))


if __name__ == "__main__":
    unittest.main()

